472	 *  next number and records who opened it (the signed-in user, arriving as X-User). */
473	public class OpenClaim {
474	    public void apply(@Val Claim claim, @HttpHeaderParameter("X-User") String user, ClaimRepository repository) throws InvalidClaimStatusException {
475	        ClaimTransition.check(claim.getStatus(), ClaimStatus.OPEN);
476	        // Taking the number holds the sheet's numbers until this change commits or is refused. Then
477	        // re-check the stored status: an open of the same claim that got there first has committed by
478	        // now, so this one is refused (and its number rolls back with it).
479	        repository.takeClaimNumber(claim.getSheetId());
480	        ClaimTransition.check(ClaimStatus.valueOf(repository.storedStatus(claim.getId())), ClaimStatus.OPEN);
481	        int number = repository.lastClaimNumber(claim.getSheetId());
482	        ClaimTransition.to(claim, ClaimStatus.OPEN);
