540	/** Moves the claim to SETTLED, refusing it when its status does not allow that, and fixes its due at the
541	 *  rate its person's grade has in force on the claim's date: amount × rate / 100, rounded half up when the claim is dated before the sheet's policy date (its today when none is set), half to even otherwise, and raised to the sheet's floor (none when no rate applies),
542	 *  plus, when it is overdue (its date plus the sheet's terms is before the sheet's today), the sheet's late percent of that floored
543	 *  due for every full 30 days it is overdue, rounded the same way.
544	 *  A correction (a negative amount) gets neither the floor nor the late charge.
545	 *  The user who opened the claim (arriving as X-User) cannot settle it. A clerk (any user not made a steward)
546	 *  cannot settle a claim whose due is above the sheet's clerk limit (no limit when none is set; a claim with no due
547	 *  is within it); a steward settles any. */
548	public class SettleClaim {
549	    public void apply(@Val Claim claim, @HttpHeaderParameter("X-User") String user, PersonRepository people,
550	            RateRepository rates, SettingRepository settings, UserRoleRepository roles, SheetRepository sheets)
551	            throws InvalidClaimStatusException, SelfSettleException, ClerkLimitException {
552	        String by = user == null ? "" : user.trim();
553	        if (claim.getOpenedBy() != null && claim.getOpenedBy().equals(by)) {
554	            throw new SelfSettleException("The user who opened a claim cannot settle it.");
555	        }
556	        ClaimTransition.check(claim.getStatus(), ClaimStatus.SETTLED);
557	        Person person = people.findById(claim.getPersonId()).orElseThrow();
558	        LocalDate today = sheets.findById(claim.getSheetId()).orElseThrow().getToday();
559	        RoundingMode rounding = settings.rounding(claim.getSheetId(), claim.getDate(), today);
560	        BigDecimal due = rates.findInForce(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate())
561	                .map((r) -> claim.getAmount().multiply(r.getRate())
562	                        .divide(BigDecimal.valueOf(100), 2, rounding))
563	                .orElse(null);
564	        // A correction's due is its amount × rate, rounded, with no floor and no late charge.
565	        if (!claim.isCorrection()) {
566	            due = settings.floored(claim.getSheetId(), due);
567	        }
568	        if (due != null && !claim.isCorrection()) {
569	            LocalDate dueBy = claim.getDate().plusDays(settings.terms(claim.getSheetId()));
570	            long spans = dueBy.isBefore(today) ? ChronoUnit.DAYS.between(dueBy, today) / 30 : 0;
571	            if (spans > 0) {
572	                due = due.add(due.multiply(settings.latePct(claim.getSheetId())).multiply(BigDecimal.valueOf(spans))
573	                        .divide(BigDecimal.valueOf(100), 2, rounding));
574	            }
575	        }
576	        if (due != null && UserRole.CLERK.equals(roles.roleOf(claim.getSheetId(), by))) {
577	            BigDecimal limit = settings.clerkLimit(claim.getSheetId()).orElse(null);
578	            if (limit != null && due.compareTo(limit) > 0) {
579	                throw new ClerkLimitException("A clerk cannot settle a claim whose due is above the clerk limit of "
580	                        + limit.setScale(2).toPlainString() + ".");
581	            }
582	        }
583	        ClaimTransition.to(claim, ClaimStatus.SETTLED);
584	        claim.setSettledDue(due);
585	    }
586	}
