    <section data-testid="rates">
      <h2>Rates</h2>
      <form data-testid="rate-form" onSubmit={submit}>
        <select data-testid="rate-form-grade" value={form.grade} onChange={(e) => change({ grade: e.target.value })}>
          {GRADES.map((g) => (
            <option key={g} value={g}>
              {g}
            </option>
          ))}
        </select>
        <input
          data-testid="rate-form-pct"
          placeholder="Percent"
          inputMode="decimal"
          value={form.rate}
          onChange={(e) => change({ rate: e.target.value })}
        />
        <input
          data-testid="rate-form-from"
          type="date"
          placeholder="From (yyyy-mm-dd)"
          value={form.from}
          onChange={(e) => change({ from: e.target.value })}
        />
        <button type="submit" data-testid="rate-form-submit" disabled={save.isPending}>
          Set rate
        </button>
        {error && <span data-testid="rate-form-error">{error}</span>}
      </form>
      <table data-testid="rate-list">
        <thead>
          <tr>
            <th>Grade</th>
            <th>Rate today (%)</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => (
            <tr key={g}>
              <td>{g}</td>
              <td data-testid={`rate-current-${g}`}>{rateOf(g) ?? NA}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <table data-testid="rate-history">
        <thead>
          <tr>
            <th>Grade</th>
            <th>From</th>
            <th>Rate (%)</th>
          </tr>
        </thead>
        <tbody>
          {rates.map((r) => (
            <tr key={`${r.grade}-${r.from ?? 'start'}`} data-testid={`rate-row-${r.grade}-${r.from ?? 'start'}`}>
              <td>{r.grade}</td>
              <td data-testid="rate-from">{r.from ?? 'start'}</td>
              <td data-testid="rate-pct">{r.rate}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

function DueColumn() {
  return <th>Due</th>;
}

/** A person's due-total in cents: the already-rounded figures of their claims that count added up
 *  (0 when none counts). Undefined for n/a: their grade has no rate today and no claim keeps a figure
 *  (a settled claim's fixed due, or one dated under another grade than today's that has a due). */
export function useDueTotal() {
  const claims = useClaims().data ?? [];
  const rateOf = usePersonRate();
  const counts = useCounts();
  const claimDue = useClaimDue();
  const people = usePeople().data ?? [];
  const today = useSheetToday();
  return (personId: number) => {
    const person = people.find((p) => p.id === personId);
    const gradeToday = gradeOn(person, today);
    const figures = claims
      .filter((c) => c.personId === personId && counts(c))
      .map((c) => ({ claim: c, due: claimDue(c, rateOf(personId, c.date)) }));
    const kept = figures.some((f) => f.due !== undefined
      && (f.claim.status === 'SETTLED' || gradeOn(person, f.claim.date) !== gradeToday));
    if (rateOf(personId) === undefined && !kept) return undefined;
    return figures.reduce((n, f) => n + (f.due ?? 0n), 0n);
  };
}

// A person's due-total: n/a when their grade has no rate today, unless a claim keeps a figure.
function PersonDueTotal({ personId }: { personId: number }) {
  const due = useDueTotal()(personId);
  return <td data-testid="person-due-total">{due === undefined ? NA : show(due)}</td>;
}

// The sheet's due-total: everyone's due-total added up, skipping n/a.
function DueTotal() {
  const [sheet] = useCurrentSheet();
  const people = usePeople().data ?? [];
  const dueOf = useDueTotal();
  if (!sheet) return null;
  const sum = people.reduce((n, p) => n + (dueOf(p.id) ?? 0n), 0n);
  return (
    <section data-testid="rollup-due">
      Due total <strong data-testid="rollup-due-total">{show(sum)}</strong>
    </section>
  );
}

export const contributions = [
  HomeMain.fill({ order: 5, Component: Rates }),
  PersonColumns.fill({ order: 20, Component: DueColumn }),
  PersonCells.fill({ order: 20, Component: PersonDueTotal }),
  HomeMain.fill({ order: 21, Component: DueTotal }),
];
import { useQuery } from '@tanstack/react-query';
import { getJson, postJson } from '../../api/http';
import { useCurrentSheet } from '../session/session';
import { useClaimDue, useClaims, useCounts } from '../claims/claims';
import { hundredths, usePersonRate } from '../rates/rates';

// A period is a name, unique on the sheet, and a from and to date (yyyy-mm-dd), inclusive; no two
// periods of a sheet overlap. A claim belongs to the period whose dates contain its date, or to none.
// A period may be closed: its due-total is then the one fixed when it was closed (closedTotal), and
// no claim dated inside it can be added, edited, opened, settled or voided.
// A steward may reopen a closed period, making its due-total live again.
export type Period = { name: string; from: string; to: string; closed: boolean; closedTotal: string | null };
export type PeriodInput = { name: string; from: string; to: string };

const base = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/periods`;
export const periodsKey = (sheet: string) => ['sheet', sheet, 'periods'] as const;

/** The active sheet's periods, by from-date. */
export function usePeriods() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: periodsKey(sheet ?? ''),
    queryFn: () => getJson<{ periods: Period[] }>(base(sheet!)).then((r) => r.periods),
    enabled: !!sheet,
  });
}

export const addPeriod = (sheet: string, user: string, input: PeriodInput) => postJson<Period>(base(sheet), input, user);

export const closePeriod = (sheet: string, user: string, name: string) =>
  postJson<Period>(`${base(sheet)}/${encodeURIComponent(name)}/close`, {}, user);

export const reopenPeriod = (sheet: string, user: string, name: string) =>
  postJson<Period>(`${base(sheet)}/${encodeURIComponent(name)}/reopen`, {}, user);

/** The period whose dates contain the date, or undefined. */
export const periodOf = (periods: Period[], date: string): Period | undefined =>
  periods.find((p) => p.from <= date && date <= p.to);

/** The name of the period a date (yyyy-mm-dd) falls in on the active sheet, or undefined. */
export function usePeriodOf() {
  const periods = usePeriods().data ?? [];
  return (date: string) => periodOf(periods, date)?.name;
}

/** The closed period a date (yyyy-mm-dd) falls in on the active sheet, or undefined. */
export function useClosedPeriodOf() {
  const periods = usePeriods().data ?? [];
  return (date: string) => {
    const p = periodOf(periods, date);
    return p?.closed ? p : undefined;
  };
}

/** A period's due-total in cents: once closed, the one fixed then; otherwise the due of the claims that
 *  count whose date falls in it (n/a as 0). */
export function usePeriodDue() {
  const claims = useClaims().data ?? [];
  const rateOf = usePersonRate();
  const counts = useCounts();
  const claimDue = useClaimDue();
  return (period: Period) =>
    period.closed && period.closedTotal !== null
      ? hundredths(period.closedTotal)
      : claims
      .filter((c) => counts(c) && period.from <= c.date && c.date <= period.to)
      .reduce((n, c) => n + (claimDue(c, rateOf(c.personId, c.date)) ?? 0n), 0n);
}
import { useQuery } from '@tanstack/react-query';
import { getJson, postJson } from '../../api/http';
import { useCurrentSheet, useSheetToday } from '../session/session';
import { hundredths } from '../rates/rates';

// A sheet's settings: the clerk limit (two decimals; null: no limit). And the role each user name has
// on the sheet: clerk (any name not given one) or steward. A clerk settles only a claim whose due is
// at or below the clerk limit; a steward settles any. The floor (two decimals, 1.00 until set): a
// claim's live due is at least it. The terms (whole days, 14 until set): a claim is due by its date plus them.
// The late percent (two decimals, 0.00 until set): an overdue claim's live due gains it of its floored due for
// every full 30 days it is overdue. The policy date (null: the sheet's today): a claim dated before it rounds
// its live figures half up, one dated on or after it half to even.
export type Settings = { clerkLimit: string | null; floor: string; terms: string; latePct: string; policyDate: string | null };
export type SettingsInput = { clerkLimit: string; floor: string; terms: string; latePct: string; policyDate: string };
export type Role = 'clerk' | 'steward';
export type UserRole = { user: string; role: Role };

/** Empty (unchanged), or a whole number of days, 0 or more. */
export const TERMS = /^(\d{1,4})?$/;

export const ROLES: Role[] = ['clerk', 'steward'];

/** Empty (the sheet's today), or a date. */
export const POLICY_DATE = /^(\d{4}-\d{2}-\d{2})?$/;

/** Empty (no limit), or 0.00 or more with up to two decimals. */
export const LIMIT = /^(\d{1,12}(\.\d{1,2})?)?$/;

const base = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}`;
export const settingsKey = (sheet: string) => ['sheet', sheet, 'settings'] as const;
export const rolesKey = (sheet: string) => ['sheet', sheet, 'roles'] as const;

/** The active sheet's settings. */
export function useSettings() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: settingsKey(sheet ?? ''),
    queryFn: () => getJson<Settings>(`${base(sheet!)}/settings`),
    enabled: !!sheet,
  });
}

/** The roles assigned on the active sheet, by user name. */
export function useRoles() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: rolesKey(sheet ?? ''),
    queryFn: () => getJson<{ roles: UserRole[] }>(`${base(sheet!)}/roles`).then((r) => r.roles),
    enabled: !!sheet,
  });
}

export const saveSettings = (sheet: string, user: string, settings: SettingsInput) =>
  postJson<Settings>(`${base(sheet)}/settings`, settings, user);

export const setRole = (sheet: string, user: string, input: { user: string; role: string }) =>
  postJson<UserRole>(`${base(sheet)}/roles`, input, user);

/** The floor in force before the sheet's settings load or any is set. */
export const DEFAULT_FLOOR = '1.00';

/** The active sheet's floor in cents: a claim's live due is at least it. */
export function useFloor(): bigint {
  return hundredths(useSettings().data?.floor ?? DEFAULT_FLOOR);
}

/** The terms in force before the sheet's settings load or any is set. */
export const DEFAULT_TERMS = '14';

/** The active sheet's terms in days: a claim is due by its date plus them. */
export function useTerms(): number {
  return Number(useSettings().data?.terms ?? DEFAULT_TERMS);
}

/** Whether the user may settle a claim with this due (cents; undefined for n/a, which is within any limit). */
export function useWithinClerkLimit() {
  const limit = useSettings().data?.clerkLimit ?? null;
  const roles = useRoles().data ?? [];
  return (user: string, due: bigint | undefined) => {
    const role = roles.find((r) => r.user === user.trim())?.role ?? 'clerk';
    return role === 'steward' || limit === null || due === undefined || due <= hundredths(limit);
  };
}

/** The late percent in force before the sheet's settings load or any is set. */
export const DEFAULT_LATE_PCT = '0.00';

/** The active sheet's late percent in hundredths of a percent. */
export function useLatePct(): bigint {
  return hundredths(useSettings().data?.latePct ?? DEFAULT_LATE_PCT);
}

/** Whether a claim dated on this date (yyyy-mm-dd) rounds its live figures half up: it is dated before the
 *  sheet's policy date (its today when none is set); otherwise it rounds half to even. */
export function useRoundsHalfUp() {
  const policy = useSettings().data?.policyDate ?? null;
  const today = useSheetToday();
  return (date: string) => {
    const on = policy ?? today;
    return on !== undefined && date < on;
  };
}
import { HomeMain } from '../../slots/defs/homeMain';
import { PersonCells, PersonColumns } from '../../slots/defs/personRow';
import { usePeople } from '../people/people';
import { show, usePersonRate } from '../rates/rates';
import { useCurrentSheet } from '../session/session';
import { useClaimDue, useClaims, useCounts, useOverdue } from './claims';

function OverdueColumns() {
  return (
    <>
      <th>Overdue</th>
      <th>Overdue total</th>
    </>
  );
}

/** A person's overdue claims that count: how many, and their dues added up in cents (n/a as 0). */
function useOverdueOf() {
  const claims = useClaims().data ?? [];
  const counts = useCounts();
  const overdue = useOverdue();
  const rateOf = usePersonRate();
  const claimDue = useClaimDue();
  return (personId: number) => {
    const late = claims.filter((c) => c.personId === personId && counts(c) && overdue(c));
    const due = late.reduce((n, c) => n + (claimDue(c, rateOf(personId, c.date)) ?? 0n), 0n);
    return { count: late.length, due };
  };
}

// A person's overdue count and overdue-total: their OPEN claims that count, due by before the sheet's today.
function PersonOverdue({ personId }: { personId: number }) {
  const { count, due } = useOverdueOf()(personId);
  return (
    <>
      <td data-testid="person-overdue-count">{count}</td>
      <td data-testid="person-overdue-total">{show(due)}</td>
    </>
  );
}

// The sheet's overdue count and overdue-total: everyone's added up.
function OverdueTotal() {
  const [sheet] = useCurrentSheet();
  const people = usePeople().data ?? [];
  const overdueOf = useOverdueOf();
  if (!sheet) return null;
  const all = people.map((p) => overdueOf(p.id));
  return (
    <section data-testid="rollup-overdue">
      Overdue <strong data-testid="rollup-overdue-count">{all.reduce((n, o) => n + o.count, 0)}</strong>{' '}
      Overdue total <strong data-testid="rollup-overdue-total">{show(all.reduce((n, o) => n + o.due, 0n))}</strong>
    </section>
  );
}

export const contributions = [
  PersonColumns.fill({ order: 30, Component: OverdueColumns }),
  PersonCells.fill({ order: 30, Component: PersonOverdue }),
  HomeMain.fill({ order: 22, Component: OverdueTotal }),
];

