import { useState } from 'react';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { PersonCells, PersonColumns } from '../../slots/defs/personRow';
import { show } from '../rates/rates';
import { useDueTotal } from '../rates/rates.slot';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { addPatron, peopleKey, usePeople } from './people';

function PatronColumns() {
  return (
    <>
      <th>Patrons</th>
      <th>Backing</th>
      <th>Add patron</th>
    </>
  );
}

// A person's patrons (names, sorted), their backing (their patrons' due-totals added up, skipping n/a),
// and a picker that names another person on the sheet as a patron. A refusal shows on the row.
function PersonPatrons({ personId }: { personId: number }) {
  const [sheet] = useCurrentSheet();
  const [user] = useCurrentUser();
  const people = usePeople().data ?? [];
  const person = people.find((p) => p.id === personId);
  const dueOf = useDueTotal();
  const [choice, setChoice] = useState('');
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useSubmitOnce();

  const add = useMutation({
    mutationFn: (patronId: number) => addPatron(sheet!, user, personId, patronId),
    onSuccess: async () => {
      setChoice('');
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheet!) });
    },
    onError: async () => {
      setError('The patron could not be added: not the person themselves, nor one already named.');
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheet!) });
    },
  });

  const patronIds = person?.patronIds ?? [];
  const patrons = people.filter((p) => patronIds.includes(p.id));
  const names = patrons.map((p) => p.name).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  const backing = patrons.reduce((n, p) => n + (dueOf(p.id) ?? 0n), 0n);

  const submit = () => {
    setError('');
    if (!choice) {
      setError('Choose a patron.');
      return;
    }
    once(() => add.mutateAsync(Number(choice)));
  };

import { useState } from 'react';
import type { FormEvent } from 'react';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HomeMain } from '../../slots/defs/homeMain';
import { show } from '../rates/rates';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { addPeriod, closePeriod, periodsKey, reopenPeriod, usePeriodDue, usePeriods } from './periods';
import type { Period, PeriodInput } from './periods';

const DATE = /^\d{4}-\d{2}-\d{2}$/;

const EMPTY: PeriodInput = { name: '', from: '', to: '' };

// The sheet's periods: a form that adds one (a name unique on the sheet, from on or before to, not
// overlapping another), and each period with its dates, its due-total, whether it is closed and a button
// that closes it, and one that reopens it (a closed period, by a steward only). A refused close or reopen
// shows on its period.
function Periods() {
  const [sheet] = useCurrentSheet();
  const [user] = useCurrentUser();
  const periods = usePeriods().data ?? [];
  const dueOf = usePeriodDue();
  const [form, setForm] = useState<PeriodInput>(EMPTY);
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useSubmitOnce();
  const [periodErrors, setPeriodErrors] = useState<Record<string, string>>({});

  const close = useMutation({
    mutationFn: (name: string) => closePeriod(sheet!, user, name),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: periodsKey(sheet!) }),
    onError: async (_e, name) => {
      setPeriodErrors((e) => ({ ...e, [name]: `The period ${name} could not be closed.` }));
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheet!) });
    },
  });

  const reopen = useMutation({
    mutationFn: (name: string) => reopenPeriod(sheet!, user, name),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: periodsKey(sheet!) }),
    onError: async (_e, name) => {
      setPeriodErrors((e) => ({ ...e, [name]: `The period ${name} could not be reopened: only a steward can reopen a closed period.` }));
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheet!) });
    },
  });

  const takeReopen = (period: Period) => {
    setPeriodErrors(({ [period.name]: _, ...rest }) => rest);
    if (!period.closed) {
      setPeriodErrors((e) => ({ ...e, [period.name]: `The period ${period.name} is not closed.` }));
      return;
    }
    reopen.mutate(period.name);
  };

  const take = (period: Period) => {
    setPeriodErrors(({ [period.name]: _, ...rest }) => rest);
    if (period.closed) {
      setPeriodErrors((e) => ({ ...e, [period.name]: `The period ${period.name} is already closed.` }));
      return;
    }
    close.mutate(period.name);
  };

  const save = useMutation({
    mutationFn: (input: PeriodInput) => addPeriod(sheet!, user, input),
    onSuccess: async () => {
      setForm(EMPTY);
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheet!) });
    },
    onError: async () => {
      setError('The period could not be added: its name must be new on the sheet and its dates must not overlap another period.');
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheet!) });
    },
  });

  if (!sheet) return null;

  const change = (patch: Partial<PeriodInput>) => {
    setForm((f) => ({ ...f, ...patch }));
    setError('');
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const name = form.name.trim();
    const from = form.from.trim();
    const to = form.to.trim();
    if (name === '') {
      setError('The period must have a name.');
      return;
    }
    if (!DATE.test(from) || !DATE.test(to)) {
      setError('The from and to dates must be dates (yyyy-mm-dd).');
      return;
    }
    if (to < from) {
      setError('The to-date must be on or after the from-date.');
      return;
    }
    if (periods.some((p) => p.name === name)) {
      setError(`A period named ${name} is already on the sheet.`);
      return;
    }
    const clash = periods.find((p) => p.from <= to && from <= p.to);
    if (clash) {
      setError(`The period overlaps ${clash.name}.`);
      return;
    }
    once(() => save.mutateAsync({ name, from, to }));
import { useState } from 'react';
import type { FormEvent } from 'react';
import { HttpError } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { PeopleBar } from '../../slots/defs/peopleBar';
import { useCurrentSheet, useCurrentUser, useSheetToday } from '../session/session';
import { peopleKey } from '../people/people';
import { periodsKey, useClosedPeriodOf } from '../periods/periods';
import { claimsKey, quickAddClaim } from './claims';

/** 0.00 or more, with up to two decimals: a quick-added claim is never a correction. */
const AMOUNT = /^\d+(\.\d{1,2})?$/;

type QuickInput = { name: string; amount: string };
const EMPTY: QuickInput = { name: '', amount: '' };

// The quick-add bar: a name and an amount make a DRAFT claim dated the sheet's today, with an empty
// note, for the named person (matched ignoring case; created with grade A when not on the sheet).
// The person and claim forms' rules apply: a name is required, the amount must be 0.00 or more with
// up to two decimals, and no claim may be dated inside a closed period.
function QuickAdd() {
  const [sheet] = useCurrentSheet();
  const [user] = useCurrentUser();
  const today = useSheetToday();
  const closedOf = useClosedPeriodOf();
  const [form, setForm] = useState<QuickInput>(EMPTY);
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useSubmitOnce();

  const save = useMutation({
    mutationFn: (input: QuickInput) => quickAddClaim(sheet!, user, input),
    onSuccess: async () => {
      setForm(EMPTY);
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheet!) });
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet!) });
    },
    onError: async (e) => {
      const reason = e instanceof HttpError ? (e.body as { reason?: string } | undefined)?.reason : undefined;
      setError(reason === 'retired'
        ? 'The claim could not be added: the person retired before today.'
        : e instanceof HttpError && e.status === 409
        ? 'The claim could not be added: today is inside a closed period.'
        : 'The claim could not be added: a name is required and the amount must be 0.00 or more, with up to two decimals.');
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheet!) });
    },
  });

  const change = (patch: Partial<QuickInput>) => {
    setForm((f) => ({ ...f, ...patch }));
    setError('');
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const input = { name: form.name.trim(), amount: form.amount.trim() };
    if (!input.name) {
      setError('A person needs a name.');
      return;
    }
    if (!AMOUNT.test(input.amount)) {
      setError('The amount must be a number of 0.00 or more, with up to two decimals.');
      return;
    }
    const closed = today ? closedOf(today) : undefined;
    if (closed) {
